class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        n = len(nums)
        newNums = [0] * n
        for i, v in enumerate(nums):
            newNums[(i + k) % n] = v
        nums[:] = newNums

class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        def reverse(i: int, j: int) -> None:
            while i < j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1

        n = len(nums)
        k %= n
        reverse(0, n - 1)
        reverse(0, k - 1)
        reverse(k, n - 1)
